 "new_string": "def transform(grid):
    """Connect aligned marker pairs and recolor each touched 2-object."""
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    line = set()
    from collections import defaultdict
    by_row, by_col = defaultdict(list), defaultdict(list)
    for r, c in markers:
        by_row[r].append(c)
        by_col[c].append(r)
    for r, cols in by_row.items():
        if len(cols) >= 2:
            line.update((r, c) for c in range(min(cols), max(cols) + 1))
    for c, rows in by_col.items():
        if len(rows) >= 2:
            line.update((r, c) for r in range(min(rows), max(rows) + 1))

    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if any(cell in line for cell in component):
                for rr, cc in component:
                    out[rr][cc] = 1
    for r, c in line:
        out[r][c] = 1
    return out
