 "content": "def transform(grid):
    """Draw marker-defined lines and recolor the 2-objects those lines hit."""
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    from collections import defaultdict
    by_row, by_col = defaultdict(list), defaultdict(list)
    for r, c in markers:
        by_row[r].append(c)
        by_col[c].append(r)

    lines = []
    for r, cols in by_row.items():
        if len(cols) >= 2:
            lines.append({(r, c) for c in range(min(cols), max(cols) + 1)})
    for c, rows in by_col.items():
        if len(rows) >= 2:
            lines.append({(r, c) for r in range(min(rows), max(rows) + 1)})

    out = [row[:] for row in grid]
    # Connected 2-regions touched by a marker line are recolored as a whole.
    seen = set()
