    for r, c in markers:
        rows[r].append(c)
        cols[c].append(r)

    line = set()
    for r, cs in rows.items():
        if len(cs) >= 2:
            line.update((r, c) for c in range(min(cs), max(cs) + 1))
    for c, rs in cols.items():
        if len(rs) >= 2:
            line.update((r, c) for r in range(min(rs), max(rs) + 1))

    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
