    """Trace straight rays from each 1 marker, recoloring intersected 2 objects."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked_objects = set()
    seen = set()
    # Components of color 2 are treated as whole objects.
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                rr, cc = stack.pop()
                comp.add((rr, cc))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = rr + dr, cc + dc
                        if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2
                                and (nr, nc) not in seen):
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            components.append(comp)

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] == 2:
                        # Color the whole contiguous shape reached by the ray.
                        for comp in components:
                            if (rr, cc) in comp:
                                marked_objects.update(comp)
                                break
                    else:
                        out[rr][cc] = 1
                    rr += dr
                    cc += dc
    for rr, cc in marked_objects:
        out[rr][cc] = 1
    return out

