                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2
                            and (nr,nc) not in seen):
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            if any(rr in rows or cc in cols for rr,cc in comp):
                for rr,cc in comp:
                    out[rr][cc] = 1
    for rr in rows:
        for cc in range(w):
            out[rr][cc] = 1
    for cc in cols:
        for rr in range(h):
            out[rr][cc] = 1
