 "content": "def transform(grid):
    """Connect aligned pairs of marker pixels, recoloring any crossed 2-object."""
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    # Each aligned pair of 1 markers draws a straight segment between them.
    # Such segments in the demos span the grid edges, passing through objects.
    lines = set()
    for i, (r1, c1) in enumerate(markers):
        for r2, c2 in markers[i + 1:]:
            if r1 == r2:
                lines.update((r1, c) for c in range(min(c1, c2), max(c1, c2) + 1))
            elif c1 == c2:
                lines.update((r, c1) for r in range(min(r1, r2), max(r1, r2) + 1))

    out = [row[:] for row in grid]
    # Treat color-2 shapes as 4-connected objects; if a line crosses any cell,
    # turn the entire shape to color 1.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if any(cell in lines for cell in comp):
                for rr, cc in comp:
                    out[rr][cc] = 1

    for r, c in lines:
        out[r][c] = 1
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
